llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Procainamide, a close benzamide analogue with an aminoethyl amide side chain, has absolute oral bioavailability of 75% in normal volunteers after oral vs IV dosing, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "N-acetylprocainamide, which shares the benzamide and aminoethyl side-chain motif, has absolute bioavailability of 87.2% (range 79.2-93.0%) in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Sematilide, another benzamide with a basic aminoethyl side chain, has absolute oral bioavailability of about 58-59%, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "A morpholine-containing analogue has absolute oral bioavailability of 44 ± 15% in humans, supporting high F for the morpholine-bearing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Haloperidol, the highest-similarity analogue, has absolute oral bioavailability of 0.64 ± 0.23 in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Loperamide has very low oral bioavailability (0.3%) due to P-gp efflux and first-pass metabolism, but it is structurally distant (large lipophilic tertiary amide) and not representative of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C26"],
      "claim": "Indoramin shows low median oral bioavailability (7.7%) due to extensive first-pass metabolism, but its indole/piperidine structure and high variability limit transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small, moderately lipophilic, neutral benzamide with a morpholinoethyl amide side chain. The closest transferable experimental evidence—procainamide, N-acetylprocainamide, sematilide, and morpholine-containing analogues—shows absolute oral bioavailability well above 20% (44-87%). Low-bioavailability analogues (loperamide, indoramin) are structurally more distant and carry specific liabilities (P-gp efflux, extensive first-pass metabolism) not expected for the query. Therefore predict high F >=20%.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data for the exact query molecule.",
    "Fed-state condition is not experimentally addressed by the available evidence.",
    "Morgan similarities are moderate (0.28-0.34), so transfer is inferential.",
    "Some evidence sources show high interindividual variability (e.g., haloperidol, indoramin)."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

